CREATE TABLE IF NOT EXISTS collection_resource_lots(resource_identity_id INTEGER PRIMARY KEY REFERENCES identity_values(identity_id),item_identity_id INTEGER NOT NULL REFERENCES identity_values(identity_id),origin_identity_id INTEGER REFERENCES identity_values(identity_id),controller_identity_id INTEGER REFERENCES identity_values(identity_id),location_identity_id INTEGER REFERENCES identity_values(identity_id),current_quantity INTEGER NOT NULL CHECK(current_quantity>=0),metadata_block_id INTEGER NOT NULL REFERENCES block_values(block_id),source_stream_id BLOB NOT NULL REFERENCES producer_streams(stream_id),source_sequence BLOB NOT NULL,revision BLOB NOT NULL); CREATE INDEX IF NOT EXISTS ix_collection_resource_origin ON collection_resource_lots(item_identity_id,origin_identity_id,controller_identity_id); CREATE TABLE IF NOT EXISTS collection_resource_parents(resource_identity_id INTEGER NOT NULL REFERENCES collection_resource_lots(resource_identity_id),ordinal INTEGER NOT NULL,parent_identity_id INTEGER NOT NULL REFERENCES identity_values(identity_id),PRIMARY KEY(resource_identity_id,ordinal)) WITHOUT ROWID;
